-- ===== 04_reference_and_unknown.sql =====
-- =============================================================================
-- Step 04 — Reference data, seeded dimensions, and reserved Unknown members
-- =============================================================================
USE baseball_dw;

-- Era boundaries (top level of the date hierarchy). Conventional named eras;
-- Whalen, Matthews & Mills (2025) recover the Dead Ball, Integration, Steroid and
-- Post-Steroid eras empirically. Contiguous and covering 1871-2025.
DROP TABLE IF EXISTS ref_era;
CREATE TABLE ref_era (
  era_name    VARCHAR(40) NOT NULL,
  start_year  SMALLINT    NOT NULL,
  end_year    SMALLINT    NOT NULL,
  era_order   TINYINT     NOT NULL,
  PRIMARY KEY (era_name)
) ENGINE=InnoDB;
INSERT INTO ref_era (era_name, start_year, end_year, era_order) VALUES
  ('Nineteenth Century', 1871, 1900, 1),
  ('Dead Ball',          1901, 1919, 2),
  ('Live Ball',          1920, 1941, 3),
  ('World War II',       1942, 1946, 4),
  ('Integration',        1947, 1960, 5),
  ('Expansion',          1961, 1976, 6),
  ('Free Agency',        1977, 1993, 7),
  ('Steroid',            1994, 2005, 8),
  ('Post-Steroid',       2006, 2025, 9);

-- Reserved Unknown members (surrogate key -1) ------------------------------------
INSERT INTO dim_date (date_key, full_date, day_of_month, day_name, month_num, month_name,
                      year_month_label, season_year, era_name, era_start_year, era_end_year)
VALUES (-1, NULL, NULL, 'Unknown', NULL, 'Unknown', 'Unknown', NULL, 'Unknown', NULL, NULL);

INSERT INTO dim_season (season_key, season_year, era_name, era_start_year, era_end_year, pa_definition)
VALUES (-1, NULL, 'Unknown', NULL, NULL, 'Unknown');

INSERT INTO dim_player (player_key, lahman_player_id, retro_id, bbref_id, first_name, last_name,
                        full_name, bats, throws, birth_year, birth_country, debut_date, final_game_date)
VALUES (-1, NULL, NULL, NULL, 'Unknown', 'Unknown', 'Unknown player', '?', '?', NULL, NULL, NULL, NULL);

INSERT INTO dim_team (team_key, franchise_id, team_code_lahman, team_code_retro, team_name, division_name,
                      league_code, league_name, effective_date, end_date, is_current, version_num)
VALUES (-1, NULL, 'UNK', 'UNK', 'Unknown team', 'Unknown', 'UNK', 'Unknown', '1000-01-01', '9999-12-31', 1, 0);

INSERT INTO dim_park (park_key, park_code, park_name, city, state, country, region, region_label, city_label,
                      attribute_source)
VALUES (-1, NULL, 'Unknown park', 'Unknown', 'Unknown', 'Unknown', 'Unknown', 'Unknown', 'Unknown',
        'reserved Unknown member');

INSERT INTO dim_outcome (outcome_key, outcome_code, outcome_name, outcome_class, result_type)
VALUES (-1, NULL, 'Unknown', 'Unknown', 'Unknown');

INSERT INTO dim_game_type (game_type_key, game_type_code, game_type_name, season_phase, counts_in_official_season_stats)
VALUES (-1, NULL, 'Unknown', 'Unknown', 0);

INSERT INTO dim_matchup (matchup_key, bat_hand, pit_hand, matchup_label, platoon_status)
VALUES (-1, '-', '-', 'Unknown', 'Unknown');

-- dim_outcome: Outcome -> Outcome class -> Result type --------------------------
INSERT INTO dim_outcome (outcome_code, outcome_name, outcome_class, result_type) VALUES
  ('1B',  'Single',                    'Hit',              'On base'),
  ('2B',  'Double',                    'Hit',              'On base'),
  ('3B',  'Triple',                    'Hit',              'On base'),
  ('HR',  'Home run',                  'Hit',              'On base'),
  ('BB',  'Walk',                      'Walk',             'On base'),
  ('IBB', 'Intentional walk',          'Walk',             'On base'),
  ('HBP', 'Hit by pitch',              'Hit by pitch',     'On base'),
  ('KS',  'Strikeout, batter reached', 'Strikeout',        'Reached, no on-base credit'),
  ('K',   'Strikeout',                 'Strikeout',        'Out'),
  ('SF',  'Sacrifice fly',             'Sacrifice',        'Out'),
  ('SH',  'Sacrifice bunt',            'Sacrifice',        'Out'),
  ('XI',  'Catcher interference',      'Interference',     'Reached, no on-base credit'),
  ('ROE', 'Reached on error',          'Reached on error', 'Reached, no on-base credit'),
  ('FC',  'Fielder''s choice',         'Fielder''s choice','Reached, no on-base credit'),
  ('OUT', 'Batted-ball out',           'Out in play',      'Out'),
  ('OTH', 'Other plate appearance',    'Other',            'Out');

-- dim_game_type: Game type -> Season phase.
-- Retrosheet labels the 2018 tiebreaker games 'playoff'; MLB (and Lahman) count them
-- in official regular-season statistics, so they belong to the Regular season phase.
INSERT INTO dim_game_type (game_type_code, game_type_name, season_phase, counts_in_official_season_stats) VALUES
  ('regular',        'Regular season game',                 'Regular season', 1),
  ('playoff',        'Tiebreaker game (Retrosheet: playoff)','Regular season', 1),
  ('wildcard',       'Wild Card round',                     'Postseason',     0),
  ('divisionseries', 'Division Series',                     'Postseason',     0),
  ('lcs',            'League Championship Series',          'Postseason',     0),
  ('worldseries',    'World Series',                        'Postseason',     0),
  ('allstar',        'All-Star Game',                       'Exhibition',     0);

-- Any game type present in the data but not seeded is added, flagged Unclassified.
INSERT INTO dim_game_type (game_type_code, game_type_name, season_phase, counts_in_official_season_stats)
SELECT s.gametype, LEFT(CONCAT('Unclassified: ', s.gametype), 40), 'Unclassified', 0
FROM (SELECT DISTINCT gametype FROM stg_retro_plays WHERE gametype IS NOT NULL) s
LEFT JOIN dim_game_type g ON g.game_type_code = s.gametype
WHERE g.game_type_key IS NULL
ORDER BY s.gametype;

-- dim_matchup: junk dimension, every batter-hand x pitcher-hand combination ------
INSERT INTO dim_matchup (bat_hand, pit_hand, matchup_label, platoon_status)
SELECT b.h, p.h, CONCAT(b.h, ' vs ', p.h),
       CASE WHEN b.h IN ('L','R') AND p.h IN ('L','R')
              THEN IF(b.h <> p.h, 'Platoon advantage', 'Same side')
            WHEN b.h = 'B' AND p.h IN ('L','R') THEN 'Switch hitter, side not recorded'
            ELSE 'Hand unknown' END
FROM (SELECT 'L' AS h, 1 AS o UNION ALL SELECT 'R', 2 UNION ALL SELECT 'B', 3 UNION ALL SELECT '?', 4) b
CROSS JOIN (SELECT 'L' AS h, 1 AS o UNION ALL SELECT 'R', 2 UNION ALL SELECT '?', 3) p
ORDER BY b.o, p.o;

-- ===== 05_load_dim_date_season.sql =====
-- =============================================================================
-- Step 05 — dim_date (from a calendar range, not from fact dates) and dim_season
-- =============================================================================
USE baseball_dw;
SET SESSION cte_max_recursion_depth = 100000;

-- Day -> Month -> Season -> Era, for every calendar day 1871-01-01 .. 2025-12-31
INSERT INTO dim_date (full_date, day_of_month, day_name, month_num, month_name,
                      year_month_label, season_year, era_name, era_start_year, era_end_year)
WITH RECURSIVE cal AS (
  SELECT DATE('1871-01-01') AS d
  UNION ALL
  SELECT d + INTERVAL 1 DAY FROM cal WHERE d < DATE('2025-12-31')
)
SELECT c.d, DAY(c.d), DAYNAME(c.d), MONTH(c.d), MONTHNAME(c.d), DATE_FORMAT(c.d, '%Y-%m'),
       YEAR(c.d), COALESCE(e.era_name, 'Unassigned'), e.start_year, e.end_year
FROM cal c
LEFT JOIN ref_era e ON YEAR(c.d) BETWEEN e.start_year AND e.end_year
ORDER BY c.d;

-- Which plate-appearance components Lahman recorded, per season AND league.
-- A component counts as recorded when at least half of that league-season's
-- rows have it. Per-league because Lahman 1871-2025 mixes MLB and Negro League
-- rows whose sources tracked different categories: a handful of Negro League
-- rows with SF must not make SF "recorded" for every 1920s AL/NL row.
DROP TABLE IF EXISTS wrk_season_league_recorded;
CREATE TABLE wrk_season_league_recorded (
  yr       SMALLINT    NOT NULL,
  lg       VARCHAR(12) NOT NULL,
  hbp_rec  TINYINT     NOT NULL,
  sh_rec   TINYINT     NOT NULL,
  sf_rec   TINYINT     NOT NULL,
  PRIMARY KEY (yr, lg)
) ENGINE=InnoDB;
INSERT INTO wrk_season_league_recorded (yr, lg, hbp_rec, sh_rec, sf_rec)
SELECT CAST(yearID AS UNSIGNED) AS yr, COALESCE(lgID, '?') AS lg,
       AVG(HBP IS NOT NULL) >= 0.5, AVG(SH IS NOT NULL) >= 0.5, AVG(SF IS NOT NULL) >= 0.5
FROM stg_lahman_batting
WHERE yearID REGEXP '^[0-9]{4}$'
GROUP BY yr, lg
ORDER BY yr, lg;

-- Season-level summary for dim_season.pa_definition (same majority rule over
-- all of the season's rows).
DROP TABLE IF EXISTS wrk_season_recorded;
CREATE TABLE wrk_season_recorded (
  yr       SMALLINT NOT NULL,
  hbp_rec  TINYINT  NOT NULL,
  sh_rec   TINYINT  NOT NULL,
  sf_rec   TINYINT  NOT NULL,
  PRIMARY KEY (yr)
) ENGINE=InnoDB;
INSERT INTO wrk_season_recorded (yr, hbp_rec, sh_rec, sf_rec)
SELECT CAST(yearID AS UNSIGNED) AS yr,
       AVG(HBP IS NOT NULL) >= 0.5, AVG(SH IS NOT NULL) >= 0.5, AVG(SF IS NOT NULL) >= 0.5
FROM stg_lahman_batting
WHERE yearID REGEXP '^[0-9]{4}$'
GROUP BY yr
ORDER BY yr;

-- Season -> Era (conformed roll-up of dim_date: same season and era values)
INSERT INTO dim_season (season_year, era_name, era_start_year, era_end_year, pa_definition)
WITH RECURSIVE yrs AS (
  SELECT 1871 AS y
  UNION ALL
  SELECT y + 1 FROM yrs WHERE y < 2025
)
SELECT y.y, COALESCE(e.era_name, 'Unassigned'), e.start_year, e.end_year,
       CASE WHEN r.yr IS NULL THEN 'No batting data'
            ELSE CONCAT_WS('+', 'AB', 'BB', IF(r.hbp_rec = 1, 'HBP', NULL),
                           IF(r.sh_rec = 1, 'SH', NULL), IF(r.sf_rec = 1, 'SF', NULL)) END
FROM yrs y
LEFT JOIN ref_era e ON y.y BETWEEN e.start_year AND e.end_year
LEFT JOIN wrk_season_recorded r ON r.yr = y.y
ORDER BY y.y;

-- ===== 06_load_dim_player.sql =====
-- =============================================================================
-- Step 06 — dim_player (Lahman People). SCD Type 1: corrections overwrite.
-- =============================================================================
USE baseball_dw;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_player', source_file, source_row, NULL, 'MISSING_NATURAL_KEY', 'People.playerID is blank'
FROM stg_lahman_people
WHERE playerID IS NULL
ORDER BY source_file, source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_player', source_file, source_row, playerID, 'DUPLICATE_NATURAL_KEY',
       'Repeated People.playerID; first occurrence kept'
FROM (SELECT p.*, ROW_NUMBER() OVER (PARTITION BY playerID ORDER BY source_file, source_row) AS rn
      FROM stg_lahman_people p WHERE playerID IS NOT NULL) d
WHERE rn > 1
ORDER BY source_file, source_row;

INSERT INTO dim_player (lahman_player_id, retro_id, bbref_id, first_name, last_name, full_name,
                        bats, throws, birth_year, birth_country, debut_date, final_game_date)
SELECT playerID, retroID, bbrefID,
       LEFT(COALESCE(nameFirst, ''), 60), LEFT(COALESCE(nameLast, ''), 60),
       LEFT(TRIM(CONCAT(COALESCE(nameFirst, ''), ' ', COALESCE(nameLast, ''))), 130),
       CASE WHEN UPPER(bats)   IN ('L','R','B') THEN UPPER(bats)   ELSE '?' END,
       CASE WHEN UPPER(throws) IN ('L','R')     THEN UPPER(throws) ELSE '?' END,
       CASE WHEN birthYear REGEXP '^[0-9]{4}$' THEN CAST(birthYear AS UNSIGNED) END,
       LEFT(birthCountry, 40),
       CASE WHEN debut REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN STR_TO_DATE(LEFT(debut, 10), '%Y-%m-%d')
            WHEN debut REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(debut, '%c/%e/%Y') END,
       CASE WHEN finalGame REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN STR_TO_DATE(LEFT(finalGame, 10), '%Y-%m-%d')
            WHEN finalGame REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(finalGame, '%c/%e/%Y') END
FROM (SELECT p.*, ROW_NUMBER() OVER (PARTITION BY playerID ORDER BY source_file, source_row) AS rn
      FROM stg_lahman_people p WHERE playerID IS NOT NULL) d
WHERE rn = 1
ORDER BY playerID;

-- Lookup used by the plate-appearance fact: Retrosheet ID -> player surrogate key.
-- If a Retrosheet ID were ever shared by two People rows, the lowest key is used
-- and the duplicate is reported by step 11.
DROP TABLE IF EXISTS wrk_player_retro;
CREATE TABLE wrk_player_retro (
  retro_id    VARCHAR(12) NOT NULL,
  player_key  INT         NOT NULL,
  n_rows      INT         NOT NULL,
  PRIMARY KEY (retro_id)
) ENGINE=InnoDB;
INSERT INTO wrk_player_retro (retro_id, player_key, n_rows)
SELECT retro_id, MIN(player_key), COUNT(*)
FROM dim_player
WHERE retro_id IS NOT NULL
GROUP BY retro_id
ORDER BY retro_id;

-- ===== 07_load_dim_team_scd2.sql =====
-- =============================================================================
-- Step 07 — dim_team, SCD Type 2 (Lahman Teams)
-- Natural key: franchise_id (Lahman franchID) alone. Tracked (Type 2)
-- attributes: team name, league, division, Lahman team code, Retrosheet team
-- code. Consecutive franchise-seasons with the same tracked values form one
-- version ("gaps and islands"); (franchise_id, effective_date) is unique.
--
-- Franchise-seasons with two team rows: Lahman 1871-2025 includes Negro League
-- franchises that changed city or league during a season (e.g. the Crawfords,
-- PC, in 1939). Lahman gives no mid-season date, so one season cannot be split
-- into two versions. The franchise-season takes its tracked attributes from
-- the team row with the most games (ties: team code order); both team rows map
-- to that version, and the count is reported as franchise_seasons_multi_team.
-- =============================================================================
USE baseball_dw;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_team', source_file, source_row, CONCAT_WS('|', yearID, teamID, franchID),
       'MISSING_NATURAL_KEY', 'Teams row lacks yearID, teamID, franchID, or lgID'
FROM stg_lahman_teams
WHERE yearID IS NULL OR NOT (yearID REGEXP '^[0-9]{4}$') OR teamID IS NULL OR franchID IS NULL OR lgID IS NULL
ORDER BY source_file, source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_team', source_file, source_row, CONCAT_WS('|', yearID, teamID), 'DUPLICATE_NATURAL_KEY',
       'Repeated (yearID, teamID); first occurrence kept'
FROM (SELECT t.*, ROW_NUMBER() OVER (PARTITION BY yearID, teamID ORDER BY source_file, source_row) AS rn
      FROM stg_lahman_teams t
      WHERE yearID REGEXP '^[0-9]{4}$' AND teamID IS NOT NULL AND franchID IS NOT NULL AND lgID IS NOT NULL) d
WHERE rn > 1
ORDER BY source_file, source_row;

-- One row per team-season (the grain of Teams.csv)
DROP TABLE IF EXISTS wrk_team_season;
CREATE TABLE wrk_team_season (
  yr                SMALLINT     NOT NULL,
  team_code_lahman  VARCHAR(4)   NOT NULL,
  franchise_id      VARCHAR(4)   NOT NULL,
  team_code_retro   VARCHAR(4)   NOT NULL,
  team_name         VARCHAR(60)  NOT NULL,
  league_code       VARCHAR(3)   NOT NULL,
  div_code          VARCHAR(2)   NULL,
  games             INT          NULL,
  PRIMARY KEY (yr, team_code_lahman)
) ENGINE=InnoDB;
INSERT INTO wrk_team_season (yr, team_code_lahman, franchise_id, team_code_retro, team_name, league_code,
                             div_code, games)
SELECT CAST(yearID AS UNSIGNED), teamID, franchID, COALESCE(teamIDretro, teamID),
       LEFT(COALESCE(name, teamID), 60), lgID, divID,
       CASE WHEN G REGEXP '^[0-9]+$' THEN CAST(G AS SIGNED) END
FROM (SELECT t.*, ROW_NUMBER() OVER (PARTITION BY yearID, teamID ORDER BY source_file, source_row) AS rn
      FROM stg_lahman_teams t
      WHERE yearID REGEXP '^[0-9]{4}$' AND teamID IS NOT NULL AND franchID IS NOT NULL AND lgID IS NOT NULL) d
WHERE rn = 1
ORDER BY yearID, teamID;

-- One row per franchise-season: the primary team row supplies the attributes
DROP TABLE IF EXISTS wrk_franchise_season;
CREATE TABLE wrk_franchise_season (
  franchise_id      VARCHAR(4)   NOT NULL,
  yr                SMALLINT     NOT NULL,
  team_code_lahman  VARCHAR(4)   NOT NULL,
  team_code_retro   VARCHAR(4)   NOT NULL,
  team_name         VARCHAR(60)  NOT NULL,
  league_code       VARCHAR(3)   NOT NULL,
  div_code          VARCHAR(2)   NULL,
  n_teams           INT          NOT NULL,
  PRIMARY KEY (franchise_id, yr)
) ENGINE=InnoDB;
INSERT INTO wrk_franchise_season (franchise_id, yr, team_code_lahman, team_code_retro, team_name,
                                  league_code, div_code, n_teams)
SELECT franchise_id, yr, team_code_lahman, team_code_retro, team_name, league_code, div_code, n_teams
FROM (SELECT w.*,
             ROW_NUMBER() OVER (PARTITION BY franchise_id, yr ORDER BY games DESC, team_code_lahman) AS rn,
             COUNT(*)     OVER (PARTITION BY franchise_id, yr) AS n_teams
      FROM wrk_team_season w) x
WHERE rn = 1
ORDER BY franchise_id, yr;

-- Versions: islands of consecutive franchise-seasons with identical tracked attributes
DROP TABLE IF EXISTS wrk_team_version;
CREATE TABLE wrk_team_version (
  franchise_id      VARCHAR(4)   NOT NULL,
  ver               INT          NOT NULL,
  start_yr          SMALLINT     NOT NULL,
  end_yr            SMALLINT     NOT NULL,
  team_name         VARCHAR(60)  NOT NULL,
  league_code       VARCHAR(3)   NOT NULL,
  div_code          VARCHAR(2)   NULL,
  team_code_retro   VARCHAR(4)   NOT NULL,
  team_code_lahman  VARCHAR(4)   NOT NULL,
  seasons           INT          NOT NULL,
  PRIMARY KEY (franchise_id, ver)
) ENGINE=InnoDB;
INSERT INTO wrk_team_version (franchise_id, ver, start_yr, end_yr, team_name, league_code, div_code,
                              team_code_retro, team_code_lahman, seasons)
WITH a AS (
  SELECT f.*, CONCAT_WS('|', team_name, league_code, COALESCE(div_code, '-'), team_code_retro, team_code_lahman) AS attr
  FROM wrk_franchise_season f
), c AS (
  SELECT a.*, CASE WHEN LAG(attr) OVER (PARTITION BY franchise_id ORDER BY yr) <=> attr THEN 0 ELSE 1 END AS chg
  FROM a
), v AS (
  SELECT c.*, SUM(chg) OVER (PARTITION BY franchise_id ORDER BY yr
                             ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS ver
  FROM c
)
SELECT franchise_id, ver, MIN(yr), MAX(yr), team_name, league_code, div_code, team_code_retro, team_code_lahman, COUNT(*)
FROM v
GROUP BY franchise_id, ver, team_name, league_code, div_code, team_code_retro, team_code_lahman
ORDER BY franchise_id, ver;

INSERT INTO dim_team (franchise_id, team_code_lahman, team_code_retro, team_name, division_name,
                      league_code, league_name, effective_date, end_date, is_current, version_num)
SELECT v.franchise_id, v.team_code_lahman, v.team_code_retro, v.team_name,
       CASE v.div_code WHEN 'E' THEN CONCAT(v.league_code, ' East')
                       WHEN 'C' THEN CONCAT(v.league_code, ' Central')
                       WHEN 'W' THEN CONCAT(v.league_code, ' West')
                       ELSE CONCAT(v.league_code, ' (no divisions)') END,
       v.league_code,
       CASE v.league_code WHEN 'AL' THEN 'American League' WHEN 'NL' THEN 'National League'
                          WHEN 'AA' THEN 'American Association' WHEN 'UA' THEN 'Union Association'
                          WHEN 'PL' THEN 'Players League' WHEN 'FL' THEN 'Federal League'
                          WHEN 'NA' THEN 'National Association' ELSE v.league_code END,
       MAKEDATE(v.start_yr, 1),
       CASE WHEN v.ver = m.max_ver AND m.last_yr = g.max_yr THEN DATE('9999-12-31')
            ELSE DATE(CONCAT(v.end_yr, '-12-31')) END,
       IF(v.ver = m.max_ver, 1, 0),
       v.ver
FROM wrk_team_version v
JOIN (SELECT franchise_id, MAX(ver) AS max_ver, MAX(end_yr) AS last_yr
      FROM wrk_team_version GROUP BY franchise_id) m ON m.franchise_id = v.franchise_id
CROSS JOIN (SELECT MAX(yr) AS max_yr FROM wrk_team_season) g
ORDER BY v.franchise_id, v.start_yr;

-- Surrogate-key lookups used by both fact loads: every team-season (including a
-- franchise's second team row in a season) maps to the franchise's version for
-- that season. Versions of one franchise never overlap, so the match is unique.
DROP TABLE IF EXISTS wrk_team_lookup;
CREATE TABLE wrk_team_lookup (
  yr                SMALLINT    NOT NULL,
  team_code_lahman  VARCHAR(4)  NOT NULL,
  team_code_retro   VARCHAR(4)  NOT NULL,
  team_key          INT         NOT NULL,
  PRIMARY KEY (yr, team_code_lahman)
) ENGINE=InnoDB;
INSERT INTO wrk_team_lookup (yr, team_code_lahman, team_code_retro, team_key)
SELECT w.yr, w.team_code_lahman, w.team_code_retro, d.team_key
FROM wrk_team_season w
JOIN dim_team d ON d.franchise_id = w.franchise_id
               AND w.yr BETWEEN YEAR(d.effective_date) AND YEAR(d.end_date)
ORDER BY w.yr, w.team_code_lahman;

DROP TABLE IF EXISTS wrk_team_retro_lookup;
CREATE TABLE wrk_team_retro_lookup (
  yr               SMALLINT    NOT NULL,
  team_code_retro  VARCHAR(4)  NOT NULL,
  team_key         INT         NOT NULL,
  n_rows           INT         NOT NULL,
  PRIMARY KEY (yr, team_code_retro)
) ENGINE=InnoDB;
INSERT INTO wrk_team_retro_lookup (yr, team_code_retro, team_key, n_rows)
SELECT yr, team_code_retro, MIN(team_key), COUNT(*)
FROM wrk_team_lookup
GROUP BY yr, team_code_retro
ORDER BY yr, team_code_retro;

-- ===== 08_load_dim_park.sql =====
-- =============================================================================
-- Step 08 — dim_park. Natural key = Retrosheet site code.
-- Attributes come from the park lookup file chosen by the stager (the file whose
-- codes best match the site codes in plays). Site codes missing from the lookup
-- are still added so every fact row has a real park member; their attributes
-- are 'Unknown' and counted in the verification report.
--
-- Hierarchy Park -> City -> Region -> Country:
--   region       = state/province when the lookup gives one, otherwise the
--                  country (parks in Japan, the UK, Australia, Mexico ... have
--                  no state, so the level repeats its parent instead of being empty)
--   region_label = 'Region, Country'        (unique Region member; just the
--                  country when there is no state)
--   city_label   = 'City, Region, Country'  (unique City member; 'City, Country'
--                  when there is no state)
-- =============================================================================
USE baseball_dw;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_park', source_file, source_row, NULL, 'MISSING_NATURAL_KEY', 'Park lookup row has no park code'
FROM stg_park_lookup
WHERE park_code IS NULL
ORDER BY source_file, source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'dim_park', source_file, source_row, park_code, 'DUPLICATE_NATURAL_KEY',
       'Repeated park code; first occurrence kept'
FROM (SELECT s.*, ROW_NUMBER() OVER (PARTITION BY park_code ORDER BY source_file, source_row) AS rn
      FROM stg_park_lookup s WHERE park_code IS NOT NULL) d
WHERE rn > 1
ORDER BY source_file, source_row;

INSERT INTO dim_park (park_code, park_name, city, state, country, region, region_label, city_label,
                      attribute_source)
SELECT park_code, park_name, city, state, country, region,
       LEFT(IF(state = 'None', country, CONCAT(region, ', ', country)), 90),
       LEFT(IF(state = 'None', CONCAT(city, ', ', country), CONCAT(city, ', ', region, ', ', country)), 160),
       'park lookup file'
FROM (SELECT park_code,
             LEFT(COALESCE(park_name, CONCAT('Park ', park_code)), 100) AS park_name,
             LEFT(COALESCE(city, 'Unknown'), 60)                        AS city,
             LEFT(COALESCE(state, 'None'), 40)                          AS state,
             LEFT(COALESCE(country, 'Unknown'), 40)                     AS country,
             LEFT(COALESCE(state, country, 'Unknown'), 40)              AS region,
             ROW_NUMBER() OVER (PARTITION BY park_code ORDER BY source_file, source_row) AS rn
      FROM stg_park_lookup s WHERE park_code IS NOT NULL) d
WHERE rn = 1
ORDER BY park_code;

INSERT INTO dim_park (park_code, park_name, city, state, country, region, region_label, city_label,
                      attribute_source)
SELECT s.site, CONCAT('Park ', s.site), 'Unknown', 'Unknown', 'Unknown', 'Unknown', 'Unknown', 'Unknown',
       'site code only (not in lookup)'
FROM (SELECT DISTINCT site FROM stg_retro_plays WHERE site IS NOT NULL) s
LEFT JOIN dim_park d ON d.park_code = s.site
WHERE d.park_key IS NULL
ORDER BY s.site;

-- ===== 09_load_fact_player_season.sql =====
-- =============================================================================
-- Step 09 — fact_player_season (Lahman Batting)
-- Grain: one row per player, per season, per stint.
-- Plate appearances (derived, era-aware):
--   PA = AB + BB + HBP + SH + SF, where a component that was not a recorded
--   category in that season and league (blank in more than half of the
--   league-season's rows, e.g. SF before 1954) adds 0. If a component is blank
--   on this row but recorded for its league that season, PA stays NULL.
--   Source columns are never coerced: a blank SF stays NULL in sac_flies.
-- =============================================================================
USE baseball_dw;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_player_season', source_file, source_row, CONCAT_WS('|', playerID, yearID, stint),
       'MISSING_GRAIN_KEY', 'playerID, yearID, or stint blank or non-numeric'
FROM stg_lahman_batting
WHERE playerID IS NULL OR yearID IS NULL OR NOT (yearID REGEXP '^[0-9]{4}$')
   OR stint IS NULL OR NOT (stint REGEXP '^[0-9]+$')
ORDER BY source_file, source_row;

DROP TABLE IF EXISTS wrk_batting_valid;
CREATE TABLE wrk_batting_valid (
  source_file VARCHAR(255) NOT NULL, source_row INT NOT NULL,
  playerID VARCHAR(20) NOT NULL, yr SMALLINT NOT NULL, stint TINYINT UNSIGNED NOT NULL, teamID VARCHAR(5) NULL,
  rn INT NOT NULL,
  PRIMARY KEY (source_file, source_row),
  KEY ix_wbv_grain (playerID, yr, stint)
) ENGINE=InnoDB;
INSERT INTO wrk_batting_valid (source_file, source_row, playerID, yr, stint, teamID, rn)
SELECT source_file, source_row, playerID, CAST(yearID AS UNSIGNED), CAST(stint AS UNSIGNED), teamID,
       ROW_NUMBER() OVER (PARTITION BY playerID, CAST(yearID AS UNSIGNED), CAST(stint AS UNSIGNED)
                          ORDER BY source_file, source_row)
FROM stg_lahman_batting
WHERE playerID IS NOT NULL AND yearID REGEXP '^[0-9]{4}$' AND stint REGEXP '^[0-9]+$'
ORDER BY source_file, source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_player_season', source_file, source_row, CONCAT_WS('|', playerID, yr, stint),
       'DUPLICATE_GRAIN', 'Repeated (playerID, yearID, stint); first occurrence kept'
FROM wrk_batting_valid
WHERE rn > 1
ORDER BY source_file, source_row;

-- A row whose player is not in dim_player cannot be placed at the grain
-- (two such rows would collide on the Unknown member), so it is rejected.
INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_player_season', w.source_file, w.source_row, CONCAT_WS('|', w.playerID, w.yr, w.stint),
       'PLAYER_NOT_IN_DIMENSION', 'Batting.playerID has no People row'
FROM wrk_batting_valid w
LEFT JOIN dim_player p ON p.lahman_player_id = w.playerID
WHERE w.rn = 1 AND p.player_key IS NULL
ORDER BY w.source_file, w.source_row;

INSERT INTO fact_player_season (player_key, season_key, team_key, stint, games, at_bats, runs, hits,
                                doubles, triples, home_runs, rbi, stolen_bases, caught_stealing, walks,
                                strikeouts, intentional_walks, hit_by_pitch, sac_hits, sac_flies, gidp,
                                plate_appearances)
SELECT p.player_key, COALESCE(s.season_key, -1), COALESCE(t.team_key, -1), w.stint,
       x.g, x.ab, x.r, x.h, x.b2, x.b3, x.hr, x.rbi, x.sb, x.cs, x.bb, x.so, x.ibb, x.hbp, x.sh, x.sf, x.gidp,
       CASE WHEN x.ab IS NULL OR x.bb IS NULL THEN NULL
            WHEN (x.hbp IS NULL AND COALESCE(r.hbp_rec, 0) = 1)
              OR (x.sh  IS NULL AND COALESCE(r.sh_rec,  0) = 1)
              OR (x.sf  IS NULL AND COALESCE(r.sf_rec,  0) = 1) THEN NULL
            ELSE x.ab + x.bb + COALESCE(x.hbp, 0) + COALESCE(x.sh, 0) + COALESCE(x.sf, 0) END
FROM wrk_batting_valid w
JOIN stg_lahman_batting b ON b.source_file = w.source_file AND b.source_row = w.source_row
JOIN dim_player p ON p.lahman_player_id = w.playerID
LEFT JOIN dim_season s ON s.season_year = w.yr
LEFT JOIN wrk_team_lookup t ON t.yr = w.yr AND t.team_code_lahman = w.teamID
LEFT JOIN wrk_season_league_recorded r ON r.yr = w.yr AND r.lg = COALESCE(b.lgID, '?')
CROSS JOIN LATERAL (
  SELECT CASE WHEN b.G    REGEXP '^[0-9]+$' THEN CAST(b.G    AS SIGNED) END AS g,
         CASE WHEN b.AB   REGEXP '^[0-9]+$' THEN CAST(b.AB   AS SIGNED) END AS ab,
         CASE WHEN b.R    REGEXP '^[0-9]+$' THEN CAST(b.R    AS SIGNED) END AS r,
         CASE WHEN b.H    REGEXP '^[0-9]+$' THEN CAST(b.H    AS SIGNED) END AS h,
         CASE WHEN b.X2B  REGEXP '^[0-9]+$' THEN CAST(b.X2B  AS SIGNED) END AS b2,
         CASE WHEN b.X3B  REGEXP '^[0-9]+$' THEN CAST(b.X3B  AS SIGNED) END AS b3,
         CASE WHEN b.HR   REGEXP '^[0-9]+$' THEN CAST(b.HR   AS SIGNED) END AS hr,
         CASE WHEN b.RBI  REGEXP '^[0-9]+$' THEN CAST(b.RBI  AS SIGNED) END AS rbi,
         CASE WHEN b.SB   REGEXP '^[0-9]+$' THEN CAST(b.SB   AS SIGNED) END AS sb,
         CASE WHEN b.CS   REGEXP '^[0-9]+$' THEN CAST(b.CS   AS SIGNED) END AS cs,
         CASE WHEN b.BB   REGEXP '^[0-9]+$' THEN CAST(b.BB   AS SIGNED) END AS bb,
         CASE WHEN b.SO   REGEXP '^[0-9]+$' THEN CAST(b.SO   AS SIGNED) END AS so,
         CASE WHEN b.IBB  REGEXP '^[0-9]+$' THEN CAST(b.IBB  AS SIGNED) END AS ibb,
         CASE WHEN b.HBP  REGEXP '^[0-9]+$' THEN CAST(b.HBP  AS SIGNED) END AS hbp,
         CASE WHEN b.SH   REGEXP '^[0-9]+$' THEN CAST(b.SH   AS SIGNED) END AS sh,
         CASE WHEN b.SF   REGEXP '^[0-9]+$' THEN CAST(b.SF   AS SIGNED) END AS sf,
         CASE WHEN b.GIDP REGEXP '^[0-9]+$' THEN CAST(b.GIDP AS SIGNED) END AS gidp
) x
WHERE w.rn = 1
ORDER BY w.playerID, w.yr, w.stint;

-- ===== 10_load_fact_plate_appearance.sql =====
-- =============================================================================
-- Step 10 — fact_plate_appearance (Retrosheet plays)
-- Grain: one row per plate appearance, identified by (game_id, play_num).
-- Rows that are not plate appearances (pa = 0: stolen bases, wild pitches,
-- pickoffs ...) are outside the grain and go to etl_reject as NOT_PLATE_APPEARANCE.
-- =============================================================================
USE baseball_dw;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_plate_appearance', source_file, source_row, LEFT(CONCAT_WS('#', gid, pn), 100),
       'NOT_PLATE_APPEARANCE', LEFT(CONCAT('pa=', COALESCE(pa, 'blank'), ' event=', COALESCE(event, '')), 255)
FROM stg_retro_plays
WHERE COALESCE(pa, '') <> '1'
ORDER BY source_file, source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_plate_appearance', source_file, source_row, LEFT(CONCAT_WS('#', gid, pn), 100),
       'MISSING_GRAIN_KEY', 'gid or pn blank or non-numeric'
FROM stg_retro_plays
WHERE pa = '1' AND (gid IS NULL OR pn IS NULL OR NOT (pn REGEXP '^[0-9]+$'))
ORDER BY source_file, source_row;

-- Typed, validated plate appearances (one row per grain; duplicates flagged by rn)
DROP TABLE IF EXISTS wrk_plays_valid;
CREATE TABLE wrk_plays_valid (
  source_file   VARCHAR(255) NOT NULL,
  source_row    INT          NOT NULL,
  gid           VARCHAR(16)  NOT NULL,
  pn_num        SMALLINT     NOT NULL,
  rn            INT          NOT NULL,
  game_dt       DATE         NULL,
  season        SMALLINT     NULL,
  batter        VARCHAR(12)  NULL,
  pitcher       VARCHAR(12)  NULL,
  batteam       VARCHAR(5)   NULL,
  pitteam       VARCHAR(5)   NULL,
  site          VARCHAR(10)  NULL,
  gametype      VARCHAR(20)  NULL,
  bat_hand      CHAR(1)      NOT NULL,
  pit_hand      CHAR(1)      NOT NULL,
  outcome_code  VARCHAR(4)   NULL,
  f_ab TINYINT NOT NULL, f_single TINYINT NOT NULL, f_double TINYINT NOT NULL, f_triple TINYINT NOT NULL,
  f_hr TINYINT NOT NULL, f_walk TINYINT NOT NULL, f_iw TINYINT NOT NULL, f_hbp TINYINT NOT NULL,
  f_k TINYINT NOT NULL, f_sf TINYINT NOT NULL, f_sh TINYINT NOT NULL, f_bip TINYINT NOT NULL,
  n_rbi TINYINT NOT NULL, n_runs TINYINT NOT NULL,
  PRIMARY KEY (source_file, source_row),
  KEY ix_wpv_grain (gid, pn_num)
) ENGINE=InnoDB;

INSERT INTO wrk_plays_valid
SELECT x.source_file, x.source_row, x.gid, x.pn_num,
       ROW_NUMBER() OVER (PARTITION BY x.gid, x.pn_num ORDER BY x.source_file, x.source_row),
       x.game_dt,
       COALESCE(YEAR(x.game_dt), CASE WHEN SUBSTRING(x.gid, 4, 4) REGEXP '^[0-9]{4}$'
                                      THEN CAST(SUBSTRING(x.gid, 4, 4) AS UNSIGNED) END),
       x.batter, x.pitcher, x.batteam, x.pitteam, x.site, x.gametype,
       CASE WHEN UPPER(x.bathand) IN ('L','R','B') THEN UPPER(x.bathand) ELSE '?' END,
       CASE WHEN UPPER(x.pithand) IN ('L','R')     THEN UPPER(x.pithand) ELSE '?' END,
       -- Outcome derivation: first matching flag wins (documented precedence)
       CASE WHEN x.hr = 1 THEN 'HR' WHEN x.tr = 1 THEN '3B' WHEN x.db = 1 THEN '2B' WHEN x.si = 1 THEN '1B'
            WHEN x.iw = 1 THEN 'IBB' WHEN x.wk = 1 THEN 'BB' WHEN x.hbp = 1 THEN 'HBP'
            WHEN x.k = 1 AND x.ks = 1 THEN 'KS' WHEN x.k = 1 THEN 'K'
            WHEN x.sf = 1 THEN 'SF' WHEN x.sh = 1 THEN 'SH' WHEN x.xi = 1 THEN 'XI'
            WHEN x.roe = 1 THEN 'ROE' WHEN x.fc = 1 THEN 'FC'
            WHEN x.oo = 1 THEN 'OUT' WHEN x.nout = 1 THEN 'OTH' END,
       x.ab, x.si, x.db, x.tr, x.hr, x.wk, x.iw, x.hbp, x.k, x.sf, x.sh, x.bip, x.rbi, x.runs
FROM (
  SELECT s.source_file, s.source_row, s.gid, CAST(s.pn AS UNSIGNED) AS pn_num,
         CASE WHEN s.game_date REGEXP '^[0-9]{8}$' THEN STR_TO_DATE(s.game_date, '%Y%m%d')
              WHEN s.game_date REGEXP '^[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}$' THEN STR_TO_DATE(s.game_date, '%Y-%c-%e')
              WHEN s.game_date REGEXP '^[0-9]{4}/[0-9]{1,2}/[0-9]{1,2}$' THEN STR_TO_DATE(s.game_date, '%Y/%c/%e')
              WHEN s.game_date REGEXP '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN STR_TO_DATE(s.game_date, '%c/%e/%Y')
              WHEN SUBSTRING(s.gid, 4, 8) REGEXP '^[0-9]{8}$' THEN STR_TO_DATE(SUBSTRING(s.gid, 4, 8), '%Y%m%d')
         END AS game_dt,
         s.batter, s.pitcher, s.batteam, s.pitteam, s.site, s.gametype, s.bathand, s.pithand,
         IF(s.ab = '1', 1, 0) AS ab, IF(s.single = '1', 1, 0) AS si, IF(s.dbl = '1', 1, 0) AS db,
         IF(s.triple = '1', 1, 0) AS tr, IF(s.hr = '1', 1, 0) AS hr, IF(s.walk = '1', 1, 0) AS wk,
         IF(s.iw = '1', 1, 0) AS iw, IF(s.hbp = '1', 1, 0) AS hbp, IF(s.k = '1', 1, 0) AS k,
         IF(s.k_safe = '1', 1, 0) AS ks, IF(s.sf = '1', 1, 0) AS sf, IF(s.sh = '1', 1, 0) AS sh,
         IF(s.xi = '1', 1, 0) AS xi, IF(s.roe = '1', 1, 0) AS roe, IF(s.fc = '1', 1, 0) AS fc,
         IF(s.othout = '1', 1, 0) AS oo, IF(s.noout = '1', 1, 0) AS nout, IF(s.bip = '1', 1, 0) AS bip,
         CASE WHEN s.rbi  REGEXP '^[0-9]$' THEN CAST(s.rbi  AS UNSIGNED) ELSE 0 END AS rbi,
         CASE WHEN s.runs REGEXP '^[0-9]$' THEN CAST(s.runs AS UNSIGNED) ELSE 0 END AS runs
  FROM stg_retro_plays s
  WHERE s.pa = '1' AND s.gid IS NOT NULL AND s.pn REGEXP '^[0-9]+$'
) x
ORDER BY x.source_file, x.source_row;

INSERT INTO etl_reject (target_table, source_file, source_row, natural_key, reason_code, detail)
SELECT 'fact_plate_appearance', source_file, source_row, CONCAT(gid, '#', pn_num), 'DUPLICATE_GRAIN',
       'Repeated (gid, pn); first occurrence kept'
FROM wrk_plays_valid
WHERE rn > 1
ORDER BY source_file, source_row;

INSERT INTO fact_plate_appearance (game_id, play_num, date_key, batter_key, pitcher_key, bat_team_key,
       fld_team_key, park_key, outcome_key, game_type_key, matchup_key, pa_count, at_bat, hit,
       single_hit, double_hit, triple_hit, home_run, total_bases, walk, intentional_walk, hit_by_pitch,
       strikeout, sac_fly, sac_hit, batted_ball, rbi, runs_scored)
SELECT p.gid, p.pn_num,
       COALESCE(dd.date_key, -1), COALESCE(bp.player_key, -1), COALESCE(pp.player_key, -1),
       COALESCE(bt.team_key, -1), COALESCE(ft.team_key, -1), COALESCE(pk.park_key, -1),
       COALESCE(o.outcome_key, -1), COALESCE(gt.game_type_key, -1), COALESCE(m.matchup_key, -1),
       1, p.f_ab, p.f_single + p.f_double + p.f_triple + p.f_hr,
       p.f_single, p.f_double, p.f_triple, p.f_hr,
       p.f_single + 2 * p.f_double + 3 * p.f_triple + 4 * p.f_hr,
       p.f_walk, p.f_iw, p.f_hbp, p.f_k, p.f_sf, p.f_sh, GREATEST(p.f_bip, p.f_hr), p.n_rbi, p.n_runs
FROM wrk_plays_valid p
LEFT JOIN dim_date dd              ON dd.full_date = p.game_dt
LEFT JOIN wrk_player_retro bp      ON bp.retro_id = p.batter
LEFT JOIN wrk_player_retro pp      ON pp.retro_id = p.pitcher
LEFT JOIN wrk_team_retro_lookup bt ON bt.yr = p.season AND bt.team_code_retro = p.batteam
LEFT JOIN wrk_team_retro_lookup ft ON ft.yr = p.season AND ft.team_code_retro = p.pitteam
LEFT JOIN dim_park pk              ON pk.park_code = p.site
LEFT JOIN dim_outcome o            ON o.outcome_code = p.outcome_code
LEFT JOIN dim_game_type gt         ON gt.game_type_code = p.gametype
LEFT JOIN dim_matchup m            ON m.bat_hand = p.bat_hand AND m.pit_hand = p.pit_hand
WHERE p.rn = 1
ORDER BY p.gid, p.pn_num;

-- ===== 11_load_agg_pa_season_park.sql =====
-- =============================================================================
-- Step 11 — agg_pa_season_park (summary table; physical-design optimization)
-- Rolls fact_plate_appearance up to season x park x game type. The season
-- comes from dim_date -> dim_season, the conformed roll-up shared with
-- fact_player_season. Every measure is a SUM of the fact, so totals match the
-- fact exactly (checked in step 13).
-- =============================================================================
USE baseball_dw;

INSERT INTO agg_pa_season_park (season_key, park_key, game_type_key, pa_count, at_bat, hit, home_run,
                                batted_ball, total_bases, walk, strikeout)
SELECT COALESCE(s.season_key, -1) AS season_key, f.park_key, f.game_type_key,
       SUM(f.pa_count), SUM(f.at_bat), SUM(f.hit), SUM(f.home_run),
       SUM(f.batted_ball), SUM(f.total_bases), SUM(f.walk), SUM(f.strikeout)
FROM fact_plate_appearance AS f
JOIN dim_date AS d ON d.date_key = f.date_key
LEFT JOIN dim_season AS s ON s.season_year = d.season_year
GROUP BY COALESCE(s.season_key, -1), f.park_key, f.game_type_key
ORDER BY season_key, f.park_key, f.game_type_key;

ANALYZE TABLE agg_pa_season_park;

-- ===== 12_load_fact_reconciliation.sql =====
-- =============================================================================
-- Step 12 — fact_reconciliation (drill-across result, stored)
-- Grain: player x season x measure (H, HR) for the Retrosheet seasons.
-- Lahman side:     fact_player_season summed over stints.
-- Retrosheet side: fact_plate_appearance summed two ways —
--   regular_label: only games Retrosheet labels 'regular'
--   official:      every game with counts_in_official_season_stats = 1
--                  (adds the 2018 tiebreakers that MLB counts as regular season)
-- match_status records whether the player-season exists in one source or both.
-- =============================================================================
USE baseball_dw;

-- Seasons that have Retrosheet plate appearances (read from the summary table)
DROP TABLE IF EXISTS wrk_recon_seasons;
CREATE TABLE wrk_recon_seasons (season_key INT NOT NULL, PRIMARY KEY (season_key)) ENGINE=InnoDB;
INSERT INTO wrk_recon_seasons
SELECT DISTINCT season_key FROM agg_pa_season_park WHERE season_key <> -1 ORDER BY season_key;

DROP TABLE IF EXISTS wrk_recon_lahman;
CREATE TABLE wrk_recon_lahman (
  player_key INT NOT NULL, season_key INT NOT NULL, h INT NULL, hr INT NULL,
  PRIMARY KEY (player_key, season_key)
) ENGINE=InnoDB;
INSERT INTO wrk_recon_lahman
SELECT f.player_key, f.season_key, SUM(f.hits), SUM(f.home_runs)
FROM fact_player_season AS f
WHERE f.season_key IN (SELECT season_key FROM wrk_recon_seasons)
GROUP BY f.player_key, f.season_key
ORDER BY f.player_key, f.season_key;

DROP TABLE IF EXISTS wrk_recon_retro;
CREATE TABLE wrk_recon_retro (
  player_key INT NOT NULL, season_key INT NOT NULL,
  h_label INT NOT NULL, hr_label INT NOT NULL, h_official INT NOT NULL, hr_official INT NOT NULL,
  PRIMARY KEY (player_key, season_key)
) ENGINE=InnoDB;
INSERT INTO wrk_recon_retro
SELECT f.batter_key, s.season_key,
       SUM(CASE WHEN g.game_type_code = 'regular' THEN f.hit      ELSE 0 END),
       SUM(CASE WHEN g.game_type_code = 'regular' THEN f.home_run ELSE 0 END),
       SUM(f.hit), SUM(f.home_run)
FROM fact_plate_appearance AS f
JOIN dim_date      AS d ON d.date_key      = f.date_key
JOIN dim_season    AS s ON s.season_year   = d.season_year
JOIN dim_game_type AS g ON g.game_type_key = f.game_type_key
WHERE g.counts_in_official_season_stats = 1
  AND f.batter_key <> -1
GROUP BY f.batter_key, s.season_key
ORDER BY f.batter_key, s.season_key;

INSERT INTO fact_reconciliation (player_key, season_key, measure_code, match_status, lahman_value,
                                 retro_regular_label_value, retro_official_value, diff_regular_label, diff_official)
SELECT k.player_key, k.season_key, m.measure_code,
       CASE WHEN l.player_key IS NOT NULL AND r.player_key IS NOT NULL THEN 'both'
            WHEN l.player_key IS NOT NULL THEN 'lahman_only' ELSE 'retro_only' END,
       CASE m.measure_code WHEN 'H' THEN l.h ELSE l.hr END,
       CASE m.measure_code WHEN 'H' THEN r.h_label ELSE r.hr_label END,
       CASE m.measure_code WHEN 'H' THEN r.h_official ELSE r.hr_official END,
       CASE m.measure_code WHEN 'H' THEN l.h - r.h_label ELSE l.hr - r.hr_label END,
       CASE m.measure_code WHEN 'H' THEN l.h - r.h_official ELSE l.hr - r.hr_official END
FROM (SELECT player_key, season_key FROM wrk_recon_lahman
      UNION
      SELECT player_key, season_key FROM wrk_recon_retro) AS k
CROSS JOIN (SELECT 'H' AS measure_code UNION ALL SELECT 'HR') AS m
LEFT JOIN wrk_recon_lahman AS l ON l.player_key = k.player_key AND l.season_key = k.season_key
LEFT JOIN wrk_recon_retro  AS r ON r.player_key = k.player_key AND r.season_key = k.season_key
ORDER BY k.player_key, k.season_key, m.measure_code;

-- ===== 13_verify.sql =====
-- =============================================================================
-- Step 13 — Load verification
--   1. Load reconciliation: source rows = loaded rows + rejected rows, per table
--   2. Grain checks (must return zero rows)
--   3. Orphan checks, one per fact foreign key (must return 0)
--   4. Summary-table and reconciliation-fact totals checks
--   5. Reject and data-quality summaries
-- Lines starting with "-- @report:" are printed as headings by run_etl.py.
-- =============================================================================
USE baseball_dw;

TRUNCATE TABLE etl_load_audit;

INSERT INTO etl_load_audit
SELECT 'dim_date', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Calendar days 1871-01-01 to 2025-12-31'
FROM (SELECT DATEDIFF('2025-12-31', '1871-01-01') + 1 AS s,
             (SELECT COUNT(*) FROM dim_date WHERE date_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_date') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_season', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Seasons 1871 to 2025'
FROM (SELECT 2025 - 1871 + 1 AS s,
             (SELECT COUNT(*) FROM dim_season WHERE season_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_season') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_player', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Lahman People.csv rows'
FROM (SELECT (SELECT COUNT(*) FROM stg_lahman_people) AS s,
             (SELECT COUNT(*) FROM dim_player WHERE player_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_player') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_team', s, l, r, IF(s = l + r, 'YES', 'NO'),
       CONCAT('Lahman Teams.csv team-season rows; loaded = team-seasons assigned to one of ', v, ' SCD2 versions')
FROM (SELECT (SELECT COUNT(*) FROM stg_lahman_teams) AS s,
             (SELECT COUNT(*) FROM wrk_team_lookup) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_team') AS r,
             (SELECT COUNT(*) FROM dim_team WHERE team_key <> -1) AS v) x;

INSERT INTO etl_load_audit
SELECT 'dim_park', s, l, r, IF(s = l + r, 'YES', 'NO'),
       'Park lookup rows plus Retrosheet site codes absent from the lookup'
FROM (SELECT (SELECT COUNT(*) FROM stg_park_lookup)
           + (SELECT COUNT(*) FROM dim_park WHERE attribute_source = 'site code only (not in lookup)') AS s,
             (SELECT COUNT(*) FROM dim_park WHERE park_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_park') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_outcome', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Seeded outcome codes (step 04)'
FROM (SELECT 16 AS s,
             (SELECT COUNT(*) FROM dim_outcome WHERE outcome_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_outcome') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_game_type', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Seeded game types plus unseen codes found in plays'
FROM (SELECT 7 + (SELECT COUNT(DISTINCT gametype) FROM stg_retro_plays
                  WHERE gametype IS NOT NULL
                    AND gametype NOT IN ('regular','playoff','wildcard','divisionseries','lcs','worldseries','allstar')) AS s,
             (SELECT COUNT(*) FROM dim_game_type WHERE game_type_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_game_type') AS r) x;

INSERT INTO etl_load_audit
SELECT 'dim_matchup', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Batter hand (L,R,B,?) x pitcher hand (L,R,?)'
FROM (SELECT 4 * 3 AS s,
             (SELECT COUNT(*) FROM dim_matchup WHERE matchup_key <> -1) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'dim_matchup') AS r) x;

INSERT INTO etl_load_audit
SELECT 'fact_player_season', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Lahman Batting.csv rows'
FROM (SELECT (SELECT COUNT(*) FROM stg_lahman_batting) AS s,
             (SELECT COUNT(*) FROM fact_player_season) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'fact_player_season') AS r) x;

INSERT INTO etl_load_audit
SELECT 'fact_plate_appearance', s, l, r, IF(s = l + r, 'YES', 'NO'), 'Retrosheet plays.csv rows, 2014 + 2018 + 2023'
FROM (SELECT (SELECT COUNT(*) FROM stg_retro_plays) AS s,
             (SELECT COUNT(*) FROM fact_plate_appearance) AS l,
             (SELECT COUNT(*) FROM etl_reject WHERE target_table = 'fact_plate_appearance') AS r) x;

-- Lahman hits in the Retrosheet seasons (for the reconciliation totals check)
DROP TABLE IF EXISTS wrk_recon_lahman_check;
CREATE TABLE wrk_recon_lahman_check ENGINE=InnoDB AS
SELECT f.hits FROM fact_player_season f
WHERE f.season_key IN (SELECT season_key FROM wrk_recon_seasons);

-- Data-quality summary used on the Data Quality slide and in the design log
DROP TABLE IF EXISTS etl_dq_summary;
CREATE TABLE etl_dq_summary (
  metric      VARCHAR(60)  NOT NULL,
  value       BIGINT       NOT NULL,
  description VARCHAR(160) NOT NULL,
  PRIMARY KEY (metric)
) ENGINE=InnoDB;
INSERT INTO etl_dq_summary (metric, value, description) VALUES
 ('batting_rows_pre1954', (SELECT COUNT(*) FROM stg_lahman_batting WHERE yearID < '1954'), 'Lahman Batting rows before 1954'),
 ('sf_blank_pre1954', (SELECT COUNT(*) FROM stg_lahman_batting WHERE yearID < '1954' AND SF IS NULL), 'Batting.SF blank, seasons before 1954'),
 ('sf_blank_all', (SELECT COUNT(*) FROM stg_lahman_batting WHERE SF IS NULL), 'Batting.SF blank, all seasons'),
 ('seasons_sf_not_recorded', (SELECT COUNT(*) FROM wrk_season_recorded WHERE sf_rec = 0), 'Seasons where SF was not a recorded category (blank in most rows)'),
 ('pa_era_rule_applied', (SELECT COUNT(*) FROM fact_player_season WHERE plate_appearances IS NOT NULL AND (sac_flies IS NULL OR hit_by_pitch IS NULL OR sac_hits IS NULL)), 'Rows whose PA used the era-aware rule (an unrecorded component added 0)'),
 ('pa_left_null', (SELECT COUNT(*) FROM fact_player_season WHERE plate_appearances IS NULL), 'Rows where PA could not be derived and stays NULL'),
 ('team_seasons_code_differs', (SELECT COUNT(*) FROM wrk_team_season WHERE team_code_lahman <> team_code_retro), 'Team-seasons where Lahman teamID differs from teamIDretro'),
 ('franchise_seasons_multi_team', (SELECT COUNT(*) FROM wrk_franchise_season WHERE n_teams > 1), 'Franchise-seasons with two or more team rows (mapped to one SCD2 version)'),
 ('parks_region_is_country', (SELECT COUNT(*) FROM dim_park WHERE park_key <> -1 AND state = 'None'), 'Parks with no state/province: Region level repeats the country'),
 ('team_versions', (SELECT COUNT(*) FROM dim_team WHERE team_key <> -1), 'dim_team SCD2 versions'),
 ('franchises_with_history', (SELECT COUNT(*) FROM (SELECT franchise_id FROM dim_team WHERE team_key <> -1 GROUP BY franchise_id HAVING COUNT(*) > 1) z), 'Franchises with more than one SCD2 version'),
 ('ambiguous_retro_team_codes', (SELECT COUNT(*) FROM wrk_team_retro_lookup WHERE n_rows > 1), 'Season + Retrosheet team code pairs matching more than one team'),
 ('not_pa_rows', (SELECT COUNT(*) FROM etl_reject WHERE reason_code = 'NOT_PLATE_APPEARANCE'), 'Retrosheet rows that are not plate appearances (pa = 0)'),
 ('plays_rows', (SELECT COUNT(*) FROM stg_retro_plays), 'Retrosheet plays rows staged'),
 ('tiebreaker_pa_rows', (SELECT COUNT(*) FROM fact_plate_appearance f JOIN dim_game_type g ON g.game_type_key = f.game_type_key WHERE g.game_type_code = 'playoff'), 'Plate appearances in Retrosheet playoff (tiebreaker) games'),
 ('people_without_retro_id', (SELECT COUNT(*) FROM dim_player WHERE player_key <> -1 AND retro_id IS NULL), 'dim_player members with no Retrosheet ID'),
 ('duplicate_retro_ids', (SELECT COUNT(*) FROM wrk_player_retro WHERE n_rows > 1), 'Retrosheet IDs shared by more than one People row'),
 ('pa_unknown_batter', (SELECT COUNT(*) FROM fact_plate_appearance WHERE batter_key = -1), 'Plate appearances assigned the Unknown batter'),
 ('pa_unknown_pitcher', (SELECT COUNT(*) FROM fact_plate_appearance WHERE pitcher_key = -1), 'Plate appearances assigned the Unknown pitcher'),
 ('pa_unknown_bat_team', (SELECT COUNT(*) FROM fact_plate_appearance WHERE bat_team_key = -1), 'Plate appearances assigned the Unknown batting team'),
 ('pa_unknown_outcome', (SELECT COUNT(*) FROM fact_plate_appearance WHERE outcome_key = -1), 'Plate appearances with no recognised outcome flag'),
 ('pa_unknown_date', (SELECT COUNT(*) FROM fact_plate_appearance WHERE date_key = -1), 'Plate appearances with an unparseable date'),
 ('parks_without_attributes', (SELECT COUNT(*) FROM dim_park WHERE attribute_source = 'site code only (not in lookup)'), 'Park codes in plays not found in the park lookup'),
 ('ps_unknown_team', (SELECT COUNT(*) FROM fact_player_season WHERE team_key = -1), 'Player-season rows assigned the Unknown team');

-- @report: Source file -> staging -> warehouse row counts
SELECT x.staging_table,
       x.files,
       x.source_file_rows,
       x.staging_rows,
       IF(x.source_file_rows = x.staging_rows, 'YES', 'NO')                AS file_eq_staging,
       a.target_table                                                      AS warehouse_table,
       a.source_rows                                                       AS warehouse_source_rows,
       a.loaded_rows,
       a.rejected_rows,
       a.balanced
FROM (SELECT sa.staging_table, COUNT(*) AS files, SUM(sa.file_rows) AS source_file_rows,
             CASE sa.staging_table
               WHEN 'stg_lahman_people'  THEN (SELECT COUNT(*) FROM stg_lahman_people)
               WHEN 'stg_lahman_batting' THEN (SELECT COUNT(*) FROM stg_lahman_batting)
               WHEN 'stg_lahman_teams'   THEN (SELECT COUNT(*) FROM stg_lahman_teams)
               WHEN 'stg_retro_plays'    THEN (SELECT COUNT(*) FROM stg_retro_plays)
               WHEN 'stg_park_lookup'    THEN (SELECT COUNT(*) FROM stg_park_lookup)
             END AS staging_rows,
             CASE sa.staging_table
               WHEN 'stg_lahman_people'  THEN 'dim_player'
               WHEN 'stg_lahman_batting' THEN 'fact_player_season'
               WHEN 'stg_lahman_teams'   THEN 'dim_team'
               WHEN 'stg_retro_plays'    THEN 'fact_plate_appearance'
               WHEN 'stg_park_lookup'    THEN 'dim_park'
             END AS target_table
      FROM etl_source_audit AS sa
      GROUP BY sa.staging_table) AS x
LEFT JOIN etl_load_audit AS a ON a.target_table = x.target_table
ORDER BY x.staging_table;

-- @report: Totals check — summary table and reconciliation fact match the base facts
SELECT 'agg_pa_season_park.pa_count = SUM(fact_plate_appearance.pa_count)' AS check_name,
       (SELECT SUM(pa_count) FROM agg_pa_season_park) AS derived_total,
       (SELECT SUM(pa_count) FROM fact_plate_appearance) AS base_total,
       IF((SELECT SUM(pa_count) FROM agg_pa_season_park) = (SELECT SUM(pa_count) FROM fact_plate_appearance), 'YES', 'NO') AS ok
UNION ALL
SELECT 'agg_pa_season_park.home_run = SUM(fact_plate_appearance.home_run)',
       (SELECT SUM(home_run) FROM agg_pa_season_park), (SELECT SUM(home_run) FROM fact_plate_appearance),
       IF((SELECT SUM(home_run) FROM agg_pa_season_park) = (SELECT SUM(home_run) FROM fact_plate_appearance), 'YES', 'NO')
UNION ALL
SELECT 'agg_pa_season_park.batted_ball = SUM(fact_plate_appearance.batted_ball)',
       (SELECT SUM(batted_ball) FROM agg_pa_season_park), (SELECT SUM(batted_ball) FROM fact_plate_appearance),
       IF((SELECT SUM(batted_ball) FROM agg_pa_season_park) = (SELECT SUM(batted_ball) FROM fact_plate_appearance), 'YES', 'NO')
UNION ALL
SELECT 'fact_reconciliation lahman H = fact_player_season hits (Retrosheet seasons)',
       (SELECT COALESCE(SUM(lahman_value), 0) FROM fact_reconciliation WHERE measure_code = 'H'),
       (SELECT COALESCE(SUM(hits), 0) FROM wrk_recon_lahman_check),
       IF((SELECT COALESCE(SUM(lahman_value), 0) FROM fact_reconciliation WHERE measure_code = 'H')
          = (SELECT COALESCE(SUM(hits), 0) FROM wrk_recon_lahman_check), 'YES', 'NO')
UNION ALL
SELECT 'fact_reconciliation retro official H = fact_plate_appearance hits (official games)',
       (SELECT COALESCE(SUM(retro_official_value), 0) FROM fact_reconciliation WHERE measure_code = 'H'),
       (SELECT COALESCE(SUM(f.hit), 0) FROM fact_plate_appearance f
          JOIN dim_game_type g ON g.game_type_key = f.game_type_key
          JOIN dim_date d ON d.date_key = f.date_key
        WHERE g.counts_in_official_season_stats = 1 AND f.batter_key <> -1 AND d.season_year IS NOT NULL),
       IF((SELECT COALESCE(SUM(retro_official_value), 0) FROM fact_reconciliation WHERE measure_code = 'H')
          = (SELECT COALESCE(SUM(f.hit), 0) FROM fact_plate_appearance f
               JOIN dim_game_type g ON g.game_type_key = f.game_type_key
               JOIN dim_date d ON d.date_key = f.date_key
             WHERE g.counts_in_official_season_stats = 1 AND f.batter_key <> -1 AND d.season_year IS NOT NULL), 'YES', 'NO');

-- @report: Grain check — fact_reconciliation (expect 0 rows)
SELECT player_key, season_key, measure_code, COUNT(*) AS n
FROM fact_reconciliation
GROUP BY player_key, season_key, measure_code
HAVING COUNT(*) > 1;

-- @report: Grain check — agg_pa_season_park (expect 0 rows)
SELECT season_key, park_key, game_type_key, COUNT(*) AS n
FROM agg_pa_season_park
GROUP BY season_key, park_key, game_type_key
HAVING COUNT(*) > 1;

-- @report: Load reconciliation (source rows = loaded rows + rejected rows)
SELECT target_table, source_rows, loaded_rows, rejected_rows, balanced, source_definition
FROM etl_load_audit
ORDER BY CASE WHEN target_table LIKE 'fact%' THEN 2 ELSE 1 END, target_table;

-- @report: Grain check — fact_player_season (expect 0 rows)
SELECT player_key, season_key, stint, COUNT(*) AS n
FROM fact_player_season
GROUP BY player_key, season_key, stint
HAVING COUNT(*) > 1;

-- @report: Grain check — fact_plate_appearance (expect 0 rows)
SELECT game_id, play_num, COUNT(*) AS n
FROM fact_plate_appearance
GROUP BY game_id, play_num
HAVING COUNT(*) > 1;

